			/*
			 * "기관명 검색" 버튼(btn1)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtn1Click(e) {
			    var btn1 = e.control;
			    
			    util.Dialog.open(app, "app/itgcms/sysmgmt/02_institute/OrganizationName", "기관명 선택", 435, 560, function(e) {
			        var dialog = e.control;
			        
			        var returnValue = dialog.returnValue;
			        
			        if (returnValue != null) {
			            var arrStr = returnValue.split("|");
			            
			            var instNo = arrStr[0];
			            var instNm = arrStr[1];
			            
			            var dmOrgCode = app.lookup("dmOrgCode");
			            var orgCode = dmOrgCode.getValue("orgCode");
			            
			            if (orgCode == instNo) {
			                
			                util.Msg.alert(app, "같은 기관이 상위 기관이 될 수 없습니다.", null, function() {
			                    
			                    var dmOrgDetail = app.lookup("dmOrgDetail");
			                    dmOrgDetail.setValue("UP_INST_NO", "");
			                    
			                    var ipb10 = app.lookup("ipb10");
			                    ipb10.value = "";
			                });
			                
			            } else {
			                var dmOrgDetail = app.lookup("dmOrgDetail");
			                dmOrgDetail.setValue("UP_INST_NO", instNo);
			                dmOrgDetail.setValue("UP_APRV_INST_NO", instNo);
			                
			                var ipb10 = app.lookup("ipb10");
			                ipb10.value = instNm;
			                
			                var ipb2 = app.lookup("ipb2");
			                ipb2.value = instNm;
			            }
			        }
			        
			    }, {
			        "orgCode": ""
			    });
			    
			}

			/*
			 * "삭제" 버튼(btnDelete)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnDeleteClick(e) {
			    var btnDelete = e.control;
			    
			    if (confirm("삭제하시겠습니까?")) {
			        
			        util.Submit.send(app, "subDeleteOrganization", function(pbSuccess) {
			            if (pbSuccess) {
			                util.Msg.alert(app, "삭제되었습니다.", null, function() {
			                    app.close();
			                });
			            }
			        });
			    }
			}

			/*
			 * 콤보 박스에서 selection-change 이벤트 발생 시 호출.
			 * ComboBox Item을 선택하여 선택된 값이 저장된 후에 발생하는 이벤트.
			 * 단위시스템 콤보박스 변경 시
			 */
			function onCmb13SelectionChange(e) {
			    var cmb13 = e.control;
			    oUntSysSeCd = cmb13.value;
			    oInstType = app.lookup("cmb3").value;
			    
			    if (oInstType == null || oInstType == "") {
			        util.Msg.alert(app, "기관 유형을 선택해주세요.");
			        return;
			    }
			    
			    var a = app.lookup('tab1').getTabItems();
			    for (var i = 1; i < a.length; i++) {
			        a[i].visible = false;
			    }
			    //if (cmb13.value == "U04" || cmb13.value == "U05" || cmb13.value == "U06") {
			    //util.Tab.setVisibleTabItem(app, "tab1", 2, true); // 2:행정정보시스템
			    //} 
			    
			    if (cmb13.value == "U09") {
			        //util.Tab.setVisibleTabItem(app, "tab1", 3, true); // 3:이주배경청소년지원재단
			    }
			    
			    if (oInstType == "5" || oInstType == "8") { // 5:시도수행기관 8:시군구수행기관
			        if (cmb13.value == "U02" || cmb13.value == "U03" || cmb13.value == "U04" || cmb13.value == "U05" || cmb13.value == "U06") {
			            util.Tab.setVisibleTabItem(app, "tab1", 4, true);
			            util.Tab.setVisibleTabItem(app, "tab1", 5, true);
			            util.Tab.setVisibleTabItem(app, "tab1", 6, true);
			            util.Tab.setVisibleTabItem(app, "tab1", 7, true);
			            util.Control.setEnable(app, true, "rdb28");
			            app.lookup("dmOrgDetail").setValue("CNTER_PRECON_WRT_YN", "Y");
			        } else {
			            util.Control.setEnable(app, false, "rdb28");
			            app.lookup("dmOrgDetail").setValue("CNTER_PRECON_WRT_YN", "N");
			        }
			        if (cmb13.value == "U02") {
			            util.Tab.setVisibleTabItem(app, "tab1", 8, true);
			        }
			    } else {
			        util.Control.setEnable(app, false, "rdb28");
			        app.lookup("dmOrgDetail").setValue("CNTER_PRECON_WRT_YN", "N");
			    }
			    
			    // 자원제공주체
			    var rdb14 = app.lookup("rdb14");
			    if (app.lookup("cmb3").value != "6") {
			        if (cmb13.value == "U02" // 청소년상담복지센터
			            ||
			            cmb13.value == "U03" // 학교밖청소년지원센터 
			            ||
			            cmb13.value == "U04" // 청소년쉼터 
			            ||
			            cmb13.value == "U05" // 청소년자립지원관
			            ||
			            cmb13.value == "U06" // 청소년회복지원시설
			            ||
			            cmb13.value == "U07" // 국립청소년디딤센터
			            ||
			            cmb13.value == "U08" // 국립청소년인터넷드림마을
			            ||
			            cmb13.value == "U09" // 이주배경청소년지원재단
			            ||
			            cmb13.value == "U10" // 내일이룸학교
			        ) {
			            rdb14.value = "Y";
			            rdb14.readOnly = false;
			        } else {
			            rdb14.readOnly = false;
			        }
			    }
			    
			}

