			/*
			 * 사용자 정의 컨트롤에서 addr-change 이벤트 발생 시 호출.
			 * 주소 변경 후 이벤트 (e.userData["zipNoValue"], e.userData["roadAddrValue"], e.userData["dtlAddrValue"], e.userData["AddrRowData"])
			 */
			function onCmnaddrsearch1AddrChange(e) {
			    var cmnaddrsearch1 = e.control;
			    
			    var rowData = e.userData["AddrRowData"];
			    var tmp3 = rowData.getValue("SI_NM");
			    var tmp4 = rowData.getValue("SGG_NM");
			    
			    var admCode = rowData.getValue("ADM_CODE");
			    var admCodeSi = admCode.substring(0, 2) + "00000000";
			    var admCodeSgg = admCode.substring(0, 5) + "00000";
			    
			    var dmOrgDetail = app.lookup("dmOrgDetail");
			    dmOrgDetail.setValue("CTPV_LINK_PBADMS_RGN_CD", admCodeSi);
			    dmOrgDetail.setValue("SGG_LINK_PBADMS_RGN_CD", admCodeSgg);
			    dmOrgDetail.setValue("EMD_LINK_PBADMS_RGN_CD", admCode);
			    
			    var rgnSe = (tmp3 + (tmp4 != null && tmp4.trim() != "" ? " - " : "") + tmp4).trim();
			    var cmb6 = app.lookup("cmb6");
			    cmb6.selectItemByLabel(rgnSe);
			    var cmb7 = app.lookup("cmb7");
			    cmb7.selectItemByLabel(tmp3);
			    var cmb8 = app.lookup("cmb8");
			    cmb8.selectItemByLabel(rgnSe);
			}

